pair Q, P, R, C;

Q = (2.43,3.46);
P = (0,0);
R = (4.43,0);
C = incenter(Q,P,R);

draw(Q--P--R--cycle);
draw(incircle(Q,P,R));
draw(R--C);

label("$Q$", Q, N);
label("$P$", P, SW);
label("$R$", R, SE);
label("$C$", C, N);

[/asy]

